 }
 
@@ -892,6 +898,8 @@ static int bcm4377_enqueue(struct bcm4377_data *bcm4377,
 	if (ring->virtual)
 		return -EINVAL;
 
+	pm_runtime_get(&bcm4377->pdev->dev);
+
 	spin_lock_irqsave(&ring->lock, flags);
 
 	head = le16_to_cpu(bcm4377->ring_state->xfer_ring_head[ring->ring_id]);
@@ -974,6 +982,8 @@ static int bcm4377_enqueue(struct bcm4377_data *bcm4377,
 		spin_unlock_irqrestore(&ring->lock, flags);
 	}
 
+	pm_runtime_mark_last_busy(&bcm4377->pdev->dev);
+	pm_runtime_put_autosuspend(&bcm4377->pdev->dev);
 	return ret;
 }
 
@@ -1309,6 +1319,12 @@ static int bcm4377_hci_open(struct hci_dev *hdev)
 	struct bcm4377_data *bcm4377 = hci_get_drvdata(hdev);
 	int ret;
 
